function parseExpression(body, index) {
  if (body === '') throw new UriTemplateError(`empty expression at ${index}`, index);
  let operator = '';
  let rest = body;
  const first = body[0];
  if (OPERATORS.has(first)) {
    operator = first;
    rest = body.slice(1);
  } else if (RESERVED_OPERATORS.has(first)) {
    throw new UriTemplateError(`reserved operator '${first}' at ${index}`, index);
  }
  const variables = rest.split(',').map((text) => parseVariable(text, index));
  return { type: 'expression', operator, variables };
}

/**
 * Split a template into literal and expression parts.
 *
 * @param {string} template template text
 * @returns {({ type: 'literal', value: string } | { type: 'expression', operator: string, variables: object[] })[]}
 *   the parts in order, with adjacent literal text merged
 */
export function parse(template) {
  if (typeof template !== 'string') throw new Error('template must be a string');
  const parts = [];
  let literal = '';
  let i = 0;
  while (i < template.length) {
    const character = template[i];
    if (character === '{') {
      if (literal !== '') {
        parts.push({ type: 'literal', value: literal });
        literal = '';
      }
      const open = i;
      const close = template.indexOf('}', open + 1);
      if (close === -1) throw new UriTemplateError(`unterminated expression at ${open}`, open);
      parts.push(parseExpression(template.slice(open + 1, close), open));
      i = close + 1;
      continue;
    }
    if (character === '}') throw new UriTemplateError(`unexpected '}' at ${i}`, i);
    literal += character;
    i += 1;
  }
  if (literal !== '') parts.push({ type: 'literal', value: literal });
  return parts;
}"}

